const stageBeforeFilmExport=stage;
let filmExports=[],filmProject='',filmLoading=false;
function filmTargets(){return data.shotScript?.hierarchical?data.shots:(data.shotScript?.generation_clips?.length?data.shotScript.generation_clips:data.shots)}
function filmItems(){return filmTargets().map(s=>({target:s,video:selectedShotVideo(s)}))}
async function loadFilmExports(){if(filmLoading)return;filmLoading=true;const project=data.project_id;try{const result=await frontFetch('/api/film-export?project_id='+encodeURIComponent(project));if(project!==data.project_id)return;filmExports=result;filmProject=project;if(document.querySelector('#filmExportHistory')){drawFilmExports();const label=document.querySelector('#filmRefreshStatus');if(label)label.textContent='自动更新中 · '+new Date().toLocaleTimeString();}}catch(e){if(tab===5)toast(e.message)}finally{filmLoading=false}}
function drawFilmExports(){const box=document.querySelector('#filmExportHistory');if(!box)return;const incoming=document.createElement('div');incoming.innerHTML=filmExports.length?filmExports.map(j=>'<div data-film-id="'+esc(j.id)+'" data-film-state="'+esc(j.status)+'" class="card" style="margin-top:16px"><b>'+esc(j.partial?'片段预览':'完整成片')+' · '+esc(new Date(j.created_at).toLocaleString())+'</b><p class="subtle">'+j.items.length+' 个分镜 · '+j.duration+' 秒 · '+j.width+' × '+j.height+' · 保留原视频声音'+(j.audio_mix?.length?' · 混入'+j.audio_mix.length+'条音轨':' · 未混入配乐')+(j.subtitle_cues?.length?' · '+j.subtitle_cues.length+'条字幕':' · 无字幕')+(j.transitions?.some(t=>t.type!=='cut')?' · '+j.transitions.filter(t=>t.type!=='cut').length+'处转场':' · 直接切换')+(j.mix_levels?' · 原声'+j.mix_levels.original+'% / 配乐'+j.mix_levels.music+'% / 音效'+j.mix_levels.effects+'%':'')+'</p>'+(j.status==='completed'?'<video controls preload="metadata" src="'+esc(j.video_url)+'" style="width:100%;max-height:540px;background:#080d14;border-radius:10px"></video><p><a class="primary" href="'+esc(j.video_url)+'?download=1">下载成片 MP4</a></p>':j.status==='failed'?'<p style="color:#ff9f9f">'+esc(j.error)+'</p>':'<p>'+esc(j.phase)+' · '+j.progress+'%</p><progress max="100" value="'+j.progress+'" style="width:100%;accent-color:#abdbc7"></progress><p class="subtle">已用 '+videoTime((Date.now()-Date.parse(j.started_at||j.created_at))/1000)+' · 合成在本机后台进行</p>')+'</div>').join(''):'<div class="card" style="margin-top:16px"><p class="subtle">合成后的成片将在这里预览，每次导出都会保留记录。</p></div>';const ids=new Set(filmExports.map(j=>j.id));for(const old of [...box.children])if(!ids.has(old.dataset.filmId))old.remove();for(const next of [...incoming.children]){const old=[...box.children].find(node=>node.dataset.filmId&&node.dataset.filmId===next.dataset.filmId);if(!old)box.append(next);else if(old.dataset.filmState!==next.dataset.filmState||next.dataset.filmState!=='completed'){if(old.innerHTML!==next.innerHTML)old.replaceWith(next)}}filmExports.forEach((job,index)=>{const node=[...box.children].find(el=>el.dataset.filmId===job.id);if(node&&box.children[index]!==node)box.insertBefore(node,box.children[index]||null);});const busy=filmExports.some(j=>['queued','running'].includes(j.status));document.querySelectorAll('[data-film-start]').forEach(b=>b.disabled=busy||b.dataset.unavailable==='true')}
stage=function(){if(tab!==5)return stageBeforeFilmExport();const items=filmItems(),ready=items.filter(x=>x.video?.video_url),missing=items.filter(x=>!x.video?.video_url);document.querySelector('#panel').innerHTML='<div class="section-head"><div><h3>成片导出</h3><p>按当前主分镜顺序合成，混入已采用配乐，保留对白与原声，输出无字幕 MP4。</p></div></div><div class="card"><div class="right-title">'+esc(data.title)+' · '+ready.length+' / '+items.length+' 个分镜已就绪</div><p class="subtle">沿用第一个视频的尺寸，统一帧率；自动混入各分镜已采用的音乐与音效，保留原对白；默认不添加对白字幕。</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin:16px 0">'+items.map((x,i)=>{const v=x.video,version=(x.target.videoVersions||[]).findIndex(j=>j.id===v?.id)+1,stamp=v&&(v.finished_at||v.created_at)?new Date(v.finished_at||v.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Tokyo',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'';return '<a '+(v?.video_url?'href="'+esc(v.video_url)+'" target="_blank" rel="noopener"':'')+' style="display:block;padding:8px 12px;border-radius:8px;background:#111b27;text-decoration:none;color:'+(v?.video_url?'#abdbc7':'#f1bba5')+'" title="'+esc(v?.id||'未生成')+'">'+(i+1)+'. '+esc(x.target.shot_id||x.target.id)+' '+(v?.video_url?'✓':'待生成')+(v?'<small style="display:block;margin-top:5px;color:#a7bbcb">采用 V'+version+' · '+esc(stamp)+'</small>':'')+'</a>';}).join('')+'</div>'+(missing.length?'<p style="color:#f1bba5">缺少：'+missing.map(x=>esc(x.target.shot_id||x.target.id)).join('、')+'。全部生成后可导出完整成片。</p>':'<p>全部分镜已就绪，可以导出完整成片。</p>')+'<button class="primary" data-film-start="full" data-unavailable="'+(!items.length||!!missing.length)+'">合成完整成片</button> '+(missing.length?'<button data-film-start="partial" data-unavailable="'+!ready.length+'">仅合成已生成片段（预览）</button>':'')+'</div><p class="subtle" id="filmRefreshStatus">自动更新中…</p><div id="filmExportHistory"></div>';document.querySelectorAll('[data-film-start]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await flushDisk();if(diskConflict||lastDiskData!==JSON.stringify(data))throw Error('项目尚未保存，请先处理保存提示再合成');const partial=b.dataset.filmStart==='partial',current=filmItems(),chosen=partial?current.filter(x=>x.video?.video_url):current;if(chosen.some(x=>!x.video?.video_url))throw Error('还有分镜未生成');await frontFetch('/api/film-export',{project_id:data.project_id,title:data.title,partial,subtitles:false,audio_selections:Object.fromEntries(chosen.map(x=>[x.target.shot_id||x.target.id,x.target.audioProduction||{}])),expected_audio_count:chosen.reduce((n,x)=>n+Object.values(x.target.audioProduction||{}).filter(c=>c.enabled&&c.activeId).length,0),items:chosen.map(x=>({target_id:x.target.shot_id||x.target.id,video_id:x.video.id||x.video.job_id}))});await loadFilmExports();toast('已开始合成成片')}catch(e){toast(e.message);b.disabled=false}});if(filmProject!==data.project_id)filmExports=[];drawFilmExports();loadFilmExports()};
setInterval(()=>{if(document.querySelector('#filmExportHistory'))loadFilmExports()},2000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&document.querySelector('#filmExportHistory'))loadFilmExports();});render();
